FUNCTION_BLOCK FB_P13
VAR_INPUT
    OCCUPANCY_DETECTED : BOOL;
    ENERGY_SAVING_MODE : BOOL;
    HVAC_MODE_SELECTOR : INT;
END_VAR
VAR_OUTPUT
    SUPPLY_FAN_RUN : BOOL;
    TEMP_SETPOINT_ADJUST : INT;
END_VAR
VAR
    InitDone : BOOL := FALSE;
    StartCondition : BOOL := FALSE;
    StartDelayCounter : INT := 0;
    FanRunDelayed : BOOL := FALSE;
    TempAdjustRaw : INT := 0;
    TempAdjustLimited : INT := 0;
END_VAR

(* 30 s start delay: 30 s / 20 ms = 1500 scans. *)
StartCondition := OCCUPANCY_DETECTED AND (HVAC_MODE_SELECTOR <> 3);

IF StartCondition THEN
    IF StartDelayCounter < 1500 THEN
        StartDelayCounter := StartDelayCounter + 1;
        FanRunDelayed := FALSE;
    ELSE
        FanRunDelayed := TRUE;
    END_IF;
ELSE
    StartDelayCounter := 0;
    FanRunDelayed := FALSE;
END_IF;

(* Temperature-setpoint adjustment by mode and occupancy. *)
CASE HVAC_MODE_SELECTOR OF
    0: (* Auto *)
        IF OCCUPANCY_DETECTED THEN
            TempAdjustRaw := 0;
        ELSE
            IF ENERGY_SAVING_MODE THEN
                TempAdjustRaw := 3;
            ELSE
                TempAdjustRaw := 2;
            END_IF;
        END_IF;
    1: (* Comfort *)
        IF OCCUPANCY_DETECTED THEN
            TempAdjustRaw := 0;
        ELSE
            TempAdjustRaw := 1;
        END_IF;
    2: (* Economy *)
        IF OCCUPANCY_DETECTED THEN
            TempAdjustRaw := 0;
        ELSE
            TempAdjustRaw := 4;
        END_IF;
    3: (* Night *)
        TempAdjustRaw := 4;
    ELSE
        TempAdjustRaw := 0;
END_CASE;

(* K4: clamp to +/-4 degC. *)
IF TempAdjustRaw > 4 THEN
    TempAdjustLimited := 4;
ELSIF TempAdjustRaw < -4 THEN
    TempAdjustLimited := -4;
ELSE
    TempAdjustLimited := TempAdjustRaw;
END_IF;

(* C10: first scan outputs are OFF and 0. Then normal calculation. *)
IF NOT InitDone THEN
    SUPPLY_FAN_RUN := FALSE;
    TEMP_SETPOINT_ADJUST := 0;
    InitDone := TRUE;
ELSE
    SUPPLY_FAN_RUN := FanRunDelayed;
    TEMP_SETPOINT_ADJUST := TempAdjustLimited;
END_IF;

END_FUNCTION_BLOCK
